import React from 'react';
import HeartRain from './HeartRain';

function App() {
  return (
    <div>
      {/* Component hiệu ứng trái tim rơi */}
      <HeartRain />

      {/* Nội dung trang web của bạn */}
      <div style={{ textAlign: 'center', paddingTop: '100px' }}>
        <h1>Chào mừng bạn đến với React! ❤️</h1>
      </div>
    </div>
  );
}

export default App;
